    f'{series}{size}' for series in 'ab' for size in range(11)])
def test_auto_papersize(papertype):
    from matplotlib.backends.backend_ps import _get_papertype, papersize

    # Every ISO paper size should be selected for a figure just smaller than it.
    width, height = papersize[papertype]
    assert _get_papertype(width - 0.01, height - 0.01) == papertype


